#!/usr/bin/env python3
import base64, gzip, pathlib, subprocess, sys, tempfile

EXPECTED_PATCH_SHA256 = "4f5ae9745dc34cee6ba0eda62b1db655721c55f6491ddbb6b3d13e57fe79d62d"
PATCH_GZIP_B64 = "[... ELLIPSIZATION ...]"

def main() -> None:
    root = pathlib.Path(sys.argv[1]).resolve()
    patch = gzip.decompress(base64.b64decode(PATCH_GZIP_B64))
    import hashlib
    actual = hashlib.sha256(patch).hexdigest()
    if actual != EXPECTED_PATCH_SHA256:
        raise SystemExit(f"phase8.1 patch digest mismatch: {actual}")
    proc = subprocess.run(
        ["patch", "-p1", "--forward", "--batch"],
        cwd=root,
        input=patch,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
    )
    sys.stdout.buffer.write(proc.stdout)
    if proc.returncode != 0:
        raise SystemExit(proc.returncode)

if __name__ == "__main__":
    main()
